package android.graphics;public class LinearGradient extends Shader{final java.awt.LinearGradientPaint value;public LinearGradient(float x,float y,float xx,float yy,int first,int last,TileMode mode){value=new java.awt.LinearGradientPaint(x,y,xx,yy,new float[]{0,1},new java.awt.Color[]{new java.awt.Color(first,true),new java.awt.Color(last,true)});}public LinearGradient(float x,float y,float xx,float yy,int[] colors,float[] stops,TileMode mode){java.awt.Color[] c=new java.awt.Color[colors.length];if(stops==null){stops=new float[colors.length];for(int i=0;i<stops.length;i++)stops[i]=i/(float)(stops.length-1);}for(int i=0;i<c.length;i++)c[i]=new java.awt.Color(colors[i],true);value=new java.awt.LinearGradientPaint(x,y,xx,yy,stops,c);}java.awt.Paint paint(){return transformed(value);}}